import Foundation

// The app's seams to the outside world. Screens depend only on these
// protocols; AppModel chooses the implementation: the Remote* set in
// Remote.swift, which talks to the mobile API, or the Preview* set below,
// which runs entirely on-device for UI tests and simulator walkthroughs.

// MARK: - Curriculum

protocol CurriculumSource: Sendable {
    func loadDays() async throws -> [JourneyDay]
}

/// The real curriculum, bundled. Generated by
/// scripts/export-ios-sample-curriculum.mjs from 30_Day_Curriculum.csv. The
/// offline source now, and the cold-start fallback once the API exists.
struct BundledCurriculumSource: CurriculumSource {
    enum Failure: LocalizedError {
        case missingResource
        var errorDescription: String? { "The journey's content is missing from this build." }
    }

    func loadDays() async throws -> [JourneyDay] {
        guard let url = Bundle.main.url(forResource: "SampleCurriculum", withExtension: "json") else {
            throw Failure.missingResource
        }
        let data = try Data(contentsOf: url)
        return try JSONDecoder().decode([JourneyDay].self, from: data).sorted { $0.dayNumber < $1.dayNumber }
    }
}

// MARK: - Sign in

struct Session: Codable, Equatable, Sendable {
    /// The account's key: digits for a phone sign-in, or "apple:…" /
    /// "email:…" for an account made without a number (lib/mobile-accounts.ts).
    let phoneNumber: String
    let token: String
    /// True for a session the preview service issued locally. Used to label
    /// the experience honestly, never to change what it does.
    let isPreview: Bool
}

enum AuthError: LocalizedError, Equatable {
    case invalidPhoneNumber
    case invalidCode

    var errorDescription: String? {
        switch self {
        case .invalidPhoneNumber: "Enter a mobile number, including the area code."
        case .invalidCode: "That code doesn't match. Check the latest text and try again."
        }
    }
}

/// The ways in the sign-in screen can offer.
struct AuthOptions: Decodable, Sendable {
    var phone = true
    var apple = true
    var email = false
}

protocol AuthService: Sendable {
    func options() async -> AuthOptions
    /// Texts a one-time code to `phoneNumber` (canonical form).
    func requestCode(phoneNumber: String) async throws
    func verify(phoneNumber: String, code: String) async throws -> Session
    func signInWithApple(identityToken: String, firstName: String?) async throws -> Session
    func requestEmailCode(email: String) async throws
    func verifyEmail(_ email: String, code: String) async throws -> Session
}

extension Session {
    /// How this account signs in, read from its key.
    var signInMethod: String {
        if phoneNumber.hasPrefix("apple:") { return "apple" }
        if phoneNumber.hasPrefix("email:") { return "email" }
        return "phone"
    }
}

/// Accepts any six-digit code and issues a local token. Only ever
/// constructed in DEBUG builds launched with `-previewServices`.
struct PreviewAuthService: AuthService {
    func requestCode(phoneNumber: String) async throws {
        try await Task.sleep(for: .milliseconds(500))
    }

    func verify(phoneNumber: String, code: String) async throws -> Session {
        try await Task.sleep(for: .milliseconds(500))
        guard code.count == 6, code.allSatisfy(\.isNumber) else { throw AuthError.invalidCode }
        return Session(phoneNumber: phoneNumber, token: "preview-\(UUID().uuidString)", isPreview: true)
    }

    func options() async -> AuthOptions { AuthOptions(email: true) }

    func signInWithApple(identityToken: String, firstName: String?) async throws -> Session {
        Session(phoneNumber: "apple:preview", token: "preview-\(UUID().uuidString)", isPreview: true)
    }

    func requestEmailCode(email: String) async throws {
        try await Task.sleep(for: .milliseconds(500))
    }

    func verifyEmail(_ email: String, code: String) async throws -> Session {
        try await verify(phoneNumber: "email:preview", code: code)
    }
}

// MARK: - Companion

struct CompanionMessage: Identifiable, Codable, Hashable, Sendable {
    enum Author: String, Codable, Sendable {
        case participant, companion
    }

    let id: UUID
    let author: Author
    let text: String
    let sentAt: Date
    let dayNumber: Int?

    init(id: UUID = UUID(), author: Author, text: String, sentAt: Date = .now, dayNumber: Int?) {
        self.id = id
        self.author = author
        self.text = text
        self.sentAt = sentAt
        self.dayNumber = dayNumber
    }
}

/// The AI companion. One continuous conversation per participant — the same
/// thread SMS participants have in message_logs, which is what lets someone
/// who started by text keep their history when they move to the app.
protocol CompanionService: Sendable {
    func history() async throws -> [CompanionMessage]
    /// Sends the participant's message and returns the companion's reply.
    func send(_ text: String, dayNumber: Int) async throws -> CompanionMessage
    /// The Curious Inspector: one question back for a written reflection.
    func inspect(reflection: String, dayNumber: Int) async throws -> String
}

/// Answers without a model behind it. Replies say so plainly instead of
/// imitating the companion, so nobody mistakes a preview build for the real
/// pastoral voice.
struct PreviewCompanionService: CompanionService {
    func history() async throws -> [CompanionMessage] { [] }

    func send(_ text: String, dayNumber: Int) async throws -> CompanionMessage {
        try await Task.sleep(for: .milliseconds(700))
        return CompanionMessage(
            author: .companion,
            text: "This is a preview build, running without the journey server — your companion answers in the full app.",
            dayNumber: dayNumber
        )
    }

    func inspect(reflection: String, dayNumber: Int) async throws -> String {
        try await Task.sleep(for: .milliseconds(700))
        return "This is a preview build, running without the journey server. In the full app, a single question about what you wrote appears here."
    }
}
